package taxi.blizz.files.internal;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

/**
 * Files on the local disk below {@code blizz.files.local-dir}. Keys are generated by the server
 * and validated, so a key can never point outside the directory.
 */
@Component
class LocalFileStorage implements FileStorage {

    private static final Pattern KEY = Pattern.compile("^[a-z0-9_]+(/[a-z0-9-]+)+$");

    private final Path root;
    private final Path staging;

    LocalFileStorage(FilesProperties properties) throws IOException {
        this.root = properties.localDir().toAbsolutePath().normalize();
        this.staging = root.resolve("staging");
        Files.createDirectories(staging);
    }

    @Override
    public Path stage(InputStream body, long maxBytes) throws IOException, TooLargeException {
        Path target = Files.createTempFile(staging, "upload-", ".bin");
        long written = 0;
        byte[] buffer = new byte[64 * 1024];
        try (OutputStream out = Files.newOutputStream(target)) {
            int read;
            while ((read = body.read(buffer)) != -1) {
                written += read;
                if (written > maxBytes) {
                    throw new TooLargeException();
                }
                out.write(buffer, 0, read);
            }
        } catch (IOException | TooLargeException | RuntimeException e) {
            Files.deleteIfExists(target);
            throw e;
        }
        return target;
    }

    @Override
    public void store(Path staged, String key) throws IOException {
        Path target = resolve(key);
        Files.createDirectories(target.getParent());
        Files.move(staged, target, StandardCopyOption.ATOMIC_MOVE);
    }

    @Override
    public InputStream open(String key) throws IOException {
        return Files.newInputStream(resolve(key));
    }

    @Override
    public void delete(String key) throws IOException {
        Files.deleteIfExists(resolve(key));
    }

    private Path resolve(String key) {
        if (!KEY.matcher(key).matches()) {
            throw new IllegalArgumentException("Invalid storage key");
        }
        Path path = root.resolve(key).normalize();
        if (!path.startsWith(root)) {
            throw new IllegalArgumentException("Invalid storage key");
        }
        return path;
    }
}
